// GTM STYLE - GitHub Pages shim: Meta "records" API doesn't exist on GitHub,
// so we emulate it with localStorage. Same collections, same behaviour.
// Collections: gtm_products, gtm_cart, gtm_favorites, gtm_orders, gtm_settings
(function () {
  const KEY = (c) => "gtm_records_" + c;
  const IDEM_KEY = (c) => "gtm_idem_" + c;

  function load(c) {
    try { return JSON.parse(localStorage.getItem(KEY(c)) || "[]"); } catch { return []; }
  }
  function save(c, arr) { try { localStorage.setItem(KEY(c), JSON.stringify(arr)); } catch {} }
  function loadIdem(c) {
    try { return JSON.parse(localStorage.getItem(IDEM_KEY(c)) || "{}"); } catch { return {}; }
  }
  function saveIdem(c, map) { try { localStorage.setItem(IDEM_KEY(c), JSON.stringify(map)); } catch {} }

  const nativeFetch = window.fetch.bind(window);

  window.fetch = function (input, init) {
    let url = typeof input === "string" ? input : (input && input.url ? input.url : "");
    // Only intercept the Meta artifact "actions" endpoint
    if (url !== "actions" && !String(url).endsWith("/actions") && url !== "actions") {
      return nativeFetch(input, init);
    }
    let bodyText = "";
    try {
      if (init && typeof init.body === "string") bodyText = init.body;
      else if (typeof input === "object" && input && typeof input.text === "function") { /* not used */ }
    } catch {}
    let payload = {};
    try { payload = JSON.parse(bodyText || "{}"); } catch {}
    const action = payload.action || "";
    const args = payload.args || {};
    const collection = args.collection || "items";

    let data;
    try {
      if (action === "records.list") {
        data = { records: load(collection) };
      } else if (action === "records.create") {
        const idem = args.idempotency_key;
        if (idem) {
          const map = loadIdem(collection);
          if (map[idem]) {
            data = { id: map[idem] };
            return Promise.resolve(makeResp(data));
          }
        }
        const id = "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
        const rec = { id, value: args.value };
        if (idem) rec.idempotency_key = idem;
        const arr = load(collection);
        arr.push(rec);
        save(collection, arr);
        if (idem) { const map = loadIdem(collection); map[idem] = id; saveIdem(collection, map); }
        data = { id };
      } else if (action === "records.replace") {
        const arr = load(collection);
        const idx = arr.findIndex((r) => r.id === args.id);
        if (idx !== -1) { arr[idx] = { ...arr[idx], value: args.value }; save(collection, arr); }
        data = { id: args.id };
      } else if (action === "records.delete") {
        const arr = load(collection).filter((r) => r.id !== args.id);
        save(collection, arr);
        data = true;
      } else if (action === "records.get") {
        const rec = load(collection).find((r) => r.id === args.id) || null;
        data = rec;
      } else {
        data = null;
      }
    } catch (e) {
      return Promise.resolve(makeResp(null, e));
    }
    return Promise.resolve(makeResp(data));

    function makeResp(d, err) {
      return {
        ok: !err,
        status: err ? 500 : 200,
        json: async () => (err ? { error: String(err) } : { data: d }),
        text: async () => JSON.stringify(err ? { error: String(err) } : { data: d }),
        clone: function () { return this; },
      };
    }
  };
})();


